const raw = $input.first().json.text || $input.first().json.output || 'The research model returned no draft text.';
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const safe = raw.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const chunks = safe.match(/[\s\S]{1,3500}/g) || ['No draft content was returned.'];
return chunks.map((part, index) => ({ json: { chatId, text: 'Prismbyte draft — part ' + (index + 1) + '/' + chunks.length + '\n\n' + part } }));
